function validate([matrix]) {
  if (!Array.isArray(matrix) || matrix.length < 1 || matrix.length > 50) return 'matrix needs 1 to 50 rows.';
  const n = matrix[0].length;
  if (n < 1 || n > 50) return 'Each row needs 1 to 50 values.';
  if (matrix.some(row => !Array.isArray(row) || row.length !== n)) return 'All rows must have the same length.';
  const seen = new Set();
  for (const row of matrix) {
    for (const v of row) {
      if (!Number.isInteger(v) || v < 1 || v > 100000) return 'Each value is a whole number from 1 to 100000.';
      if (seen.has(v)) return 'All values in matrix must be different.';
      seen.add(v);
    }
  }
  return null;
}

