function generate(rand, size) {
  const pick = k => Math.floor(rand() * k);
  const m = size === 'large' ? 40 + pick(11) : 1 + pick(5);
  const n = size === 'large' ? 40 + pick(11) : 1 + pick(5);
  const top = size === 'large' || rand() < 0.5 ? 100000 : 3 * m * n;
  const seen = new Set();
  while (seen.size < m * n) seen.add(1 + pick(top));
  const values = [...seen];
  for (let i = values.length - 1; i > 0; i--) {
    const j = pick(i + 1);
    [values[i], values[j]] = [values[j], values[i]];
  }
  const matrix = Array.from({ length: m }, (_, r) => values.slice(r * n, (r + 1) * n));
  if (rand() < 0.6) {
    // Plant a lucky number: its column holds smaller values and its row larger ones.
    const sorted = [...values].sort((a, b) => a - b);
    const k = (m - 1) + pick(sorted.length - (m - 1) - (n - 1));
    const lower = sorted.slice(0, k), upper = sorted.slice(k + 1);
    for (let i = lower.length - 1; i > 0; i--) { const j = pick(i + 1); [lower[i], lower[j]] = [lower[j], lower[i]]; }
    for (let i = upper.length - 1; i > 0; i--) { const j = pick(i + 1); [upper[i], upper[j]] = [upper[j], upper[i]]; }
    const row = pick(m), col = pick(n);
    matrix[row][col] = sorted[k];
    for (let r = 0; r < m; r++) if (r !== row) matrix[r][col] = lower.pop();
    for (let c = 0; c < n; c++) if (c !== col) matrix[row][c] = upper.pop();
    const rest = [...lower, ...upper];
    for (let r = 0; r < m; r++) for (let c = 0; c < n; c++) if (r !== row && c !== col) matrix[r][c] = rest.pop();
  }
  return [matrix];
}
